    function CompleteCallQuest(player)
        local anar_data = GetUnitData(gg_unit_n029_0022)

            GiveExpForPlayer(120, player)
            GiveGoldForPlayer(200, player)
            PlayQuestCompletedSound(player-1)
            if GetLocalPlayer() == Player(player - 1) then BlzPlaySpecialEffect(anar_data.questmarker_done, ANIM_TYPE_STAND) end

    end

    function EnableCallQuest(player)
        local anar_data = GetUnitData(gg_unit_n029_0022)

            if GetLocalPlayer() == Player(player - 1) then BlzPlaySpecialEffect(anar_data.questmarker, ANIM_TYPE_STAND) end
            UnlockInteractiveOptionIdPlayer(gg_unit_n029_0022, "call_start_conv", player)
    end


    function InitCallQuest()

        Conversations()
        QuestName = GetLocalString("Зов Помощи", "A Call")
        QuestId = "call_quest_journal"
        local anar_data = GetUnitData(gg_unit_n029_0022)
        local fire = AddSpecialEffect("Doodads\\Cinematic\\TownBurningFireEmitter\\TownBurningFireEmitter.mdx", GetRectCenterX(gg_rct_bonfire), GetRectCenterY(gg_rct_bonfire))
        local z = BlzGetLocalSpecialEffectZ(fire)

        BlzSetSpecialEffectZ(fire, -100.)

        AddInteractiveOption(gg_unit_n029_0022, {
            name = GetLocalString("Зов помощи", "A call for help"),
            id = "call_start_conv",
            feedback = function(clicked, clicking, player)

                    PlayConversation("anar_call_start_conv", gg_unit_n029_0022, player)
                    LockInteractiveOptionIdPlayer(gg_unit_n029_0022, "call_start_conv", player)
                    AddJournalEntry(player, QuestId, "ReplaceableTextures\\CommandButtons\\BTNFlare.blp", QuestName, 5, false)
                    AddJournalEntryText(player, QuestId, GetConversationText("anar_call_start_conv", gg_unit_n029_0022, player), false)
                    AddJournalEntryObjective(player, QuestId, "call_quest_journal_obj", GetLocalString("Зажечь костер", "Light the bonfire"))
                    EnableJournalTrackingButton(player, QuestId, nil, GetRectCenterX(gg_rct_bonfire_trigger), GetRectCenterY(gg_rct_bonfire_trigger))
                    SendQuestMessageForPlayer(QUEST_REVEALED_STRING .. QuestName, bj_TEXT_DELAY_QUEST, player)

                    if GetLocalPlayer() == Player(player - 1) then
                        BlzPlaySpecialEffect(anar_data.questmarker, ANIM_TYPE_DEATH)
                        StartSound(QUEST_REVEALED_SOUND or bj_questDiscoveredSound)
                    end

                    AddQuestAreaForPlayer(player, MARK_TYPE_QUESTION, MARK_COMMON, 1., 100., GetRectCenterX(gg_rct_bonfire_trigger), GetRectCenterY(gg_rct_bonfire_trigger), function()
                        UnlockInteractiveOptionIdPlayer(gg_unit_n029_0022, "call_end_conv", player)
                        SendQuestMessageForPlayer(QUEST_UPDATED_STRING .. QuestName, bj_TEXT_DELAY_QUEST, player)
                        SetJournalEntryObjectiveState(player, QuestId, "call_quest_journal_obj", JOURNAL_OBJECTIVE_STATE_DONE, true)
                        if GetLocalPlayer() == Player(player - 1) then BlzSetSpecialEffectZ(fire, z) end
                    end)

                end }, 1)
        LockInteractiveOptionId(gg_unit_n029_0022, "call_start_conv")
        --=============================================================--
        AddInteractiveOption(gg_unit_n029_0022, {
            name = GetLocalString("Костер зажжен", "Bonfire lit"),
            id = "call_end_conv",
            feedback = function(clicked, clicking, player)

                    PlayConversation("anar_call_end_conv", gg_unit_n029_0022, player)
                    LockInteractiveOptionIdPlayer(gg_unit_n029_0022, "call_end_conv", player)
                    CompleteCallQuest(player)
                    RemoveJournalEntry(player, QuestId)
                    SendQuestMessageForPlayer(QUEST_DONE_STRING .. QuestName, bj_TEXT_DELAY_QUESTDONE, player)

                    if GetLocalPlayer() == Player(player - 1) then
                        BlzPlaySpecialEffect(anar_data.questmarker_done, ANIM_TYPE_DEATH)
                    end

                end }, 1)
        LockInteractiveOptionId(gg_unit_n029_0022, "call_end_conv")

